func TestMixedQueuedViewsKeepHashesAndExactlyOneTrailer(emonT *testing.T) {
	var r *port.Cells = port.NewCells()
	var scratch *port.Cells = port.NewCells()
	var first int32 = 14 + 74
	var at int32 = plan.RqOcr(r, 12, 7, 3, 1, 0, 0, 0, 0)
	plan.RqOcrLang(r, 101, 110, 103, 0)
	plan.RqOcrEnd(r, at)
	var view int32 = plan.RqOcrView(r, 13, plan.ViewBase()+1, 99, -3100, 3, 1, 0, 0, 0, 0)
	plan.RqOcrLang(r, 101, 110, 103, 0)
	plan.RqOcrEnd(r, view)
	ocrengine.OeTag(r, scratch, 1)
	ocrengine.OeTag(r, scratch, 1)
	port.AssertEq(emonT, port.CellsAt(r, 0), first, "first request length")
	port.AssertEq(emonT, port.CellsAt(r, first), 16+74, "view request length")
	port.AssertEq(emonT, port.CellsLen(r), (30+74)+74, "two canonical records")
	port.AssertEq(emonT, port.CellsAt(r, first+11), -3100, "hash cell is not a trailer marker")
	port.AssertEq(emonT, port.CellsAt(r, first+13), -3100, "view trailer follows its language")
}

func TestCompactCropsOverViewsHaveAnIndependentIdentityTail(emonT *testing.T) {
	var r *port.Cells = port.NewCells()
	var scratch *port.Cells = port.NewCells()
	var at int32 = plan.RqOcr(r, 12, plan.ViewBase()+120, 7, 1, 1536, 18, 144, 57)
	plan.RqOcrEnd(r, at)
	ocrengine.OeTag(r, scratch, 1)
	ocrengine.OeTag(r, scratch, 1)
	port.AssertEq(emonT, ocrport.OpIdentityAt(r), 10, "compact view has no hash cells or languages")
	port.AssertEq(emonT, ocrport.OpLangFirst(r), 7, "tagged compact layout")
	port.AssertEq(emonT, ocrport.OpLangCount(r), 0, "shared helper excludes the trailer")
	port.AssertEq(emonT, ocrport.OpPpLangFirst(r, 123, 456), 7, "compact layout")
	port.AssertEq(emonT, ocrport.OpPpLangCount(r, 7), 0, "identity is not parsed as language")
	port.AssertEq(emonT, port.CellsLen(r), 13+74, "one canonical trailer")
}

func TestActualViewHashDisambiguatesLanguageShapedHashCells(emonT *testing.T) {
	var compact *port.Cells = port.NewCells()
	var hashed *port.Cells = port.NewCells()
	var scratch *port.Cells = port.NewCells()
	var at int32 = plan.RqOcr(compact, 12, plan.ViewBase()+1, 7, 1, 0, 0, 0, 0)
	plan.RqOcrLang(compact, 76, 97, 116, 110)
	plan.RqOcrLang(compact, 101, 110, 103, 0)
	plan.RqOcrEnd(compact, at)
	ocrengine.OeTag(compact, scratch, 1)
	var view int32 = plan.RqOcrView(hashed, 13, plan.ViewBase()+1, 1281455214, 1701734144, 7, 1, 0, 0, 0, 0)
	plan.RqOcrEnd(hashed, view)
	ocrengine.OeTag(hashed, scratch, 1)
	port.AssertEq(emonT, ocrport.OpPpLangFirst(compact, 123, 456), 7, "two compact languages")
	port.AssertEq(emonT, ocrport.OpPpLangCount(compact, 7), 2, "both languages retained")
	port.AssertEq(emonT, ocrport.OpPpLangAt(compact, 7, 1), 1701734144, "English retained")
	port.AssertEq(emonT, ocrport.OpPpLangFirst(hashed, 1281455214, 1701734144), 9, "verified hashes are not languages")
	port.AssertEq(emonT, ocrport.OpPpLangCount(hashed, 9), 0, "hashed view has no language")
}
